package sqlcx

import (
	"context"
	"errors"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

// DB is the minimal execution interface. *pgxpool.Pool, *pgx.Conn and
// pgx.Tx satisfy it, as does the DBTX interface generated by sqlc, so the
// same handle (or transaction) serves sqlc queries and dynamic queries.
type DB interface {
	Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error)
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

var (
	// ErrTooManyRows is returned by One when the query yields more than one
	// row.
	ErrTooManyRows = errors.New("sqlcx: query returned more than one row")
	// ErrUnordered is returned by First when the query has no ORDER BY.
	ErrUnordered = errors.New("sqlcx: First requires ORDER BY; use One for single-row lookups")
	// ErrNoWhere is returned when an UPDATE or DELETE has no WHERE condition
	// and AllowFullTable was not called.
	ErrNoWhere = errors.New("sqlcx: UPDATE/DELETE without WHERE; call AllowFullTable to affect every row")
)
